// @ts-ignore
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');

const manifestText = buffer.toString('utf8');
let documents;

try {
  documents = JSON.parse(manifestText);
} catch (error) {
  throw new Error('documents.json could not be parsed. Please check JSON syntax.');
}

if (!Array.isArray(documents)) {
  throw new Error('documents.json must contain an array of document definitions.');
}

const requiredFields = ['document_id', 'title', 'category', 'file_name'];

return documents.map((document, index) => {
  for (const field of requiredFields) {
    if (!document[field]) {
      throw new Error(`Missing required field "${field}" in documents.json item ${index + 1}`);
    }
  }

  const relativeFilePath = document.file_path
    ? String(document.file_path).replace(/^data\//, '')
    : `mock-data/${document.file_name}`;

  return {
    json: {
      document_id: document.document_id,
      title: document.title,
      category: document.category,
      file_name: document.file_name,
      file_type: document.file_type || null,
      source_file_name: document.source_file_name || document.file_name,
      content_hash: document.content_hash || null,
      last_updated: document.last_updated || null,
      file_path: `/home/node/.n8n-files/data/${relativeFilePath}`
    }
  };
});

const items = $input.all();
const fileListItems = $('Create File List').all();
const output = [];

// Remove generated metadata comments and normalize whitespace.

function cleanText(text) {
  return String(text || '')
    .replace(/<!--[\s\S]*?-->/g, '')

    .replace(/\r\n/g, '\n')

    .replace(/\n{3,}/g, '\n\n')

    .trim();
}

for (
  let itemIndex = 0;
  itemIndex < items.length;
  itemIndex++
) {
  const metadata = fileListItems[itemIndex]?.json;

  if (!metadata?.document_id) {
    throw new Error(
      `Document metadata not found for item index ${itemIndex}`
    );
  }

  // @ts-ignore
  const buffer =
    await this.helpers.getBinaryDataBuffer(
      itemIndex,
      'data'
    );

  const fileContent = cleanText(
    buffer.toString('utf8')
  );

  const lines = fileContent.split('\n');

  // Prefer the final H1 because processed files may contain multiple titles.
  const h1Titles = lines
    .map((line) => {
      const match = line.match(/^#\s+(.+)$/);

      return match
        ? match[1].trim()
        : null;
    })
    .filter(Boolean);

  const documentHeading =
    h1Titles[h1Titles.length - 1] ||
    metadata.title ||
    metadata.document_id;

  let currentSectionTitle = 'Genel';
  let currentLines = [];
  let chunkIndex = 1;


  function pushSection() {
    const content = cleanText(
      currentLines.join('\n')
    );

    if (!content) {
      return;
    }

    // Format embeddings as: title: <document title> - <section title> | text: <content>

    const embeddingTitle = [
      documentHeading,
      currentSectionTitle
    ]
      .filter(Boolean)
      .join(' - ');

    const embeddingText =
      `title: ${embeddingTitle} | text: ${content}`;

    output.push({
      json: {
        // The Default Data Loader embeds this field.
        text: embeddingText,

        metadata: {
          document_id:
            metadata.document_id,

          // Keep the manifest title for frontend source attribution.
          title:
            metadata.title,

          category:
            metadata.category,

          section_title:
            currentSectionTitle,

          chunk_index:
            chunkIndex,

          file_name:
            metadata.file_name,

          source_file_name:
            metadata.source_file_name ||
            metadata.file_name,

          file_type:
            metadata.file_type || null,

          content_hash:
            metadata.content_hash || null,

          last_updated:
            metadata.last_updated || null
        }
      }
    });

    chunkIndex++;
  }

  for (const line of lines) {
    const sectionMatch =
      line.match(/^##\s+(.+)$/);

    if (sectionMatch) {
      pushSection();

      currentSectionTitle =
        sectionMatch[1].trim();

      // Exclude H2 headings because they are already included in the embedding title.
      currentLines = [];

      continue;
    }

    // Exclude H1 headings because they are already included in the embedding title.
    if (/^#\s+/.test(line)) {
      continue;
    }

    currentLines.push(line);
  }

  pushSection();
}

return output;

const validation = $input.first().json;

const expectedDocumentCount =
  $('Create File List').all().length;

throw new Error(
  [
    'Staging validation failed.',
    `total_chunks=${validation.total_chunks}`,
    `document_count=${validation.document_count}`,
    `expected_document_count=${expectedDocumentCount}`,
    `null_embeddings=${validation.null_embedding_count}`,
    `empty_texts=${validation.empty_text_count}`,
    `missing_document_ids=${validation.missing_document_id_count}`,
    `missing_chunk_indexes=${validation.missing_chunk_index_count}`,
    `duplicate_chunk_keys=${validation.duplicate_chunk_key_count}`
  ].join(' ')
);
